const sessionId = typeof $json.sessionId === 'string' ? $json.sessionId.trim() : '';
const brand = typeof $json.brand === 'string' ? $json.brand.trim().toLowerCase() : '';
const campaignId = typeof $json.campaignId === 'string' ? $json.campaignId.trim() : '';
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
let drafts = [];
let error = null;
if (!uuid.test(sessionId)) {
  error = { code: 'INVALID_SESSION', message: 'This tool needs a valid conversation session.' };
} else if (brand !== 'oddtoe' && brand !== 'datalabs') {
  error = { code: 'INVALID_BRAND', message: 'Say which brand these drafts are for: oddtoe or datalabs.' };
} else {
  try {
    const parsed = typeof $json.drafts === 'string' ? JSON.parse($json.drafts) : $json.drafts;
    if (!Array.isArray(parsed) || parsed.length === 0) {
      error = { code: 'NO_DRAFTS', message: 'Pass a JSON array of drafts, each with prospectId, to, subject and body.' };
    } else if (parsed.length > 25) {
      error = { code: 'TOO_MANY', message: 'Draft at most 25 at a time.' };
    } else {
      drafts = parsed.map((d) => ({
        prospectId: String(d.prospectId ?? '').trim(),
        to: String(d.to ?? '').trim(),
        subject: String(d.subject ?? '').trim(),
        body: String(d.body ?? ''),
        hook: String(d.hook ?? '').trim(),
        hookEvidence: String(d.hookEvidence ?? '').trim()
      }));
      const bad = drafts.find((d) => !d.prospectId || !d.to || !d.subject || !d.body);
      if (bad) error = { code: 'INCOMPLETE_DRAFT', message: 'Every draft needs prospectId, to, subject and body.' };
    }
  } catch {
    error = { code: 'INVALID_DRAFTS', message: 'The drafts value was not valid JSON.' };
  }
}
return { json: { valid: error === null, sessionId, brand, campaignId, drafts,
  proposedInput: { brand, campaignId, count: drafts.length,
    companies: drafts.map((d) => d.prospectId) },
  ...(error ? { response: { ok: false, error } } : {}) } };

const input = $('Validate Draft Input').first().json;
const body = $json;
if (body?.schemaVersion !== 1) {
  const message = typeof body?.error?.message === 'string' ? body.error.message
    : 'The prospect store could not check these drafts.';
  const code = body?.error?.code === 'OUTREACH_NOT_CONFIGURED'
    ? 'OUTREACH_NOT_CONFIGURED' : 'VALIDATION_UNAVAILABLE';
  return [{ json: { ...input, halt: true,
    response: { ok: false, error: { code, message } } } }];
}
const byId = new Map(body.results.map((r) => [r.prospectId, r]));
const approved = input.drafts.filter((d) => byId.get(d.prospectId)?.approved === true);
const rejected = body.results.filter((r) => !r.approved)
  .map((r) => ({ company: r.company, prospectId: r.prospectId, reasons: r.reasons }));
const warnings = body.results.filter((r) => r.approved && r.warnings.length > 0)
  .map((r) => ({ company: r.company, warnings: r.warnings }));
if (approved.length === 0) {
  return [{ json: { ...input, halt: true, rejected, warnings, response: { ok: false,
    error: { code: 'ALL_DRAFTS_REJECTED',
      message: 'None of those drafts passed the outreach checks. Read the reasons out and fix them before trying again.' },
    rejected } } }];
}
return approved.map((d) => ({ json: { ...d, brand: input.brand, sessionId: input.sessionId,
  campaignId: input.campaignId, rejected, warnings, halt: false } }));

const approved = $('Split Approved Drafts').all().map((i) => i.json).filter((j) => !j.halt);
const created = $input.all().map((i) => i.json);
const drafts = approved.map((d, index) => {
  const made = created[index] ?? {};
  const draftId = String(made.id ?? made.draftId ?? made.message?.id ?? '');
  return { prospectId: d.prospectId, draftId, hook: d.hook, hookEvidence: d.hookEvidence };
}).filter((d) => d.draftId !== '');
const first = approved[0] ?? {};
return [{ json: { brand: first.brand, campaignId: first.campaignId,
  sessionId: first.sessionId, drafts,
  rejected: first.rejected ?? [], warnings: first.warnings ?? [],
  createdCount: drafts.length, attempted: approved.length } }];

const collected = $('Collect Draft Ids').first().json;
const body = $json;
if (body?.schemaVersion !== 1) {
  return [{ json: { ...collected, response: { ok: false, error: {
    code: 'RECORD_FAILED',
    message: 'Gmail drafts were created but the board could not be updated. Do not send them yet; say so and check the local app.' } } } }];
}
const recorded = body.results.filter((r) => r.outcome === 'recorded');
const blocked = body.results.filter((r) => r.outcome !== 'recorded');
return [{ json: { ...collected, response: { ok: true,
  createdCount: recorded.length,
  created: recorded.map((r) => ({ company: r.company, followUpDue: r.followUpDue })),
  blocked: blocked.map((r) => ({ company: r.company, outcome: r.outcome })),
  rejected: collected.rejected, warnings: collected.warnings,
  summary: body.summary,
  guidance: 'The drafts are in Gmail and the cards moved to Emailed. Nothing has been sent — the user reviews and sends each one. Read out anything in rejected, blocked or warnings.'
} } }];

const response = $json.response;
const error = response?.ok === false ? String(response.error?.message ?? 'Tool failed') : '';
return { json: { occurredAt: new Date().toISOString(),
  sessionId: String($json.sessionId ?? ''), requestId: '',
  toolName: 'create_outreach_drafts',
  proposedInput: JSON.stringify($json.proposedInput ?? { count: $json.attempted ?? 0 }),
  result: JSON.stringify(response), error, response } };

const prepared = $('Prepare Audit').item.json;
const response = { ...prepared.response };
if (!Number.isInteger($json.id)) {
  response.auditWarning = 'The tool result could not be written to the local audit table.';
}
return { json: response };
